import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3 } = ctx.THREE;

  const mainGroup = new Group();
  const cleanupTasks = [];

  // Palette extraction
  const pal = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // 1. BACKING PANEL WITH ENGINEERED TS-GRADIENT
  const panelWidth = 5.5;
  const panelHeight = 1.8;
  const panelGeo = new PlaneGeometry(panelWidth, panelHeight);

  // Gradient Material using TSL
  const uvs = uv();
  // Vertical smooth gradient from deep surface to ink depth
  const gradNode = mix(color(pal.surface), color(pal.ink), uvs.y);
  // Elegant bottom accent pinstripe (very sharp boundary)
  const pinstripe = smoothstep(0.0, 0.02, uvs.y).mul(1.0).sub(smoothstep(0.02, 0.04, uvs.y));
  const finalColorNode = mix(gradNode, color(pal.accent), pinstripe.mul(0.8));

  const panelMat = new MeshBasicNodeMaterial({
    colorNode: finalColorNode,
    transparent: true,
    opacity: 0.95
  });

  const panelMesh = new Mesh(panelGeo, panelMat);
  mainGroup.add(panelMesh);
  cleanupTasks.push(() => {
    panelGeo.dispose();
    panelMat.dispose();
  });

  // 2. HERO IMAGE PLANE (cta-hero-isolated.png)
  const imageSize = 1.4;
  const imageGeo = new PlaneGeometry(imageSize, imageSize * 0.625);
  const imageMat = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.0 // start invisible, fade in on load
  });
  const imageMesh = new Mesh(imageGeo, imageMat);
  // Positioned beautifully to the right side of the title card
  imageMesh.position.set(1.6, 0, 0.02);
  mainGroup.add(imageMesh);

  cleanupTasks.push(() => {
    imageGeo.dispose();
    imageMat.dispose();
  });

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      imageMat.map = tex;
      imageMat.needsUpdate = true;
      gsap.to(imageMat, { opacity: 0.85, duration: 0.8, ease: 'power2.out' });
    }).catch(err => console.warn('Failed to load pricing hero image:', err));
  }

  // 3. TYPOGRAPHY / TEXT
  // Grab standard or override text content safely
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const pricingTitleStr = textItems.find(t => t.role === 'headline')?.text ?? 'Pricing';

  // Render the primary headline "Pricing"
  const titleTextObj = ctx.fontAtlas.createText(pricingTitleStr, {
    fontSize: 52, // Bold, scale-matched
    color: pal.paper,
    align: 'left',
    letterSpacingPx: 1.5
  });
  // Position on the left side of the panel
  titleTextObj.position.set(-2.2, -0.15, 0.03);
  mainGroup.add(titleTextObj);

  // Subtle aesthetic sub-label matching the Nova Atelier theme ("INDEX / PRICING & TIERS")
  const subLabelObj = ctx.fontAtlas.createText('05 / VALUE PROPOSITION', {
    fontSize: 11,
    color: pal.accent,
    align: 'left',
    letterSpacingPx: 2.0
  });
  subLabelObj.position.set(-2.2, 0.4, 0.03);
  mainGroup.add(subLabelObj);

  // 4. WEIGHED SETTLE ENTRANCE ANIMATION
  // Slight offset translation & scale pop on initial mount
  mainGroup.position.y += 0.3;
  mainGroup.scale.set(0.97, 0.97, 0.97);

  const entranceTimeline = gsap.timeline();
  entranceTimeline.to(mainGroup.position, {
    y: '-=0.3',
    duration: 0.9,
    ease: 'power4.out'
  });
  entranceTimeline.to(mainGroup.scale, {
    x: 1.0,
    y: 1.0,
    z: 1.0,
    duration: 0.9,
    ease: 'power4.out'
  }, '<');

  cleanupTasks.push(() => {
    entranceTimeline.kill();
  });

  // Clean-up handler
  mainGroup.userData = {
    handlers: {},
    cleanup: () => {
      cleanupTasks.forEach(task => task());
    }
  };

  return mainGroup;
}
